input.command:
cd /tmp && rm -f mig_test.db && sqlite3 mig_test.db <<'EOF'
CREATE TABLE orders (id INTEGER PRIMARY KEY, shipped_at TEXT, cancelled_at TEXT, refunded_at TEXT);
INSERT INTO orders VALUES
 (1, NULL, NULL, NULL),                              -- never shipped
 (2, '2026-08-01', NULL, NULL),                      -- shipped
 (3, '2026-08-02', NULL, '2026-08-10'),              -- shipped then refunded
 (4, NULL, '2026-08-03', NULL),                      -- cancelled before shipping
 (5, '', NULL, NULL);                                -- empty-string shipped_at (bad data)
.echo on
ALTER TABLE orders ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'pending';
CREATE INDEX idx_orders_status ON orders(status);
UPDATE orders SET status = 'fulfilled' WHERE shipped_at IS NOT NULL;
.echo off
.mode column
.headers on
SELECT id, shipped_at, cancelled_at, refunded_at, status FROM orders;
SELECT status, COUNT(*) n FROM orders GROUP BY status;
EOF
echo "=== second run (re-apply) ==="
sqlite3 mig_test.db <<'EOF'
ALTER TABLE orders ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'pending';
CREATE INDEX idx_orders_status ON orders(status);
UPDATE orders SET status = 'fulfilled' WHERE shipped_at IS NOT NULL;
EOF
echo "exit=$?"
